    const groupMask=i=>'polygon('+groupRegions[i].map(([x,y])=>(x/1403*100).toFixed(3)+'% '+(y/1121*100).toFixed(3)+'%').join(',')+')';
    const escapeText=value=>String(value).replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
